const start = $('Worker Start V2').first().json;
const body = start.body ?? start;
return [{ json: {
  generation_run_id: body.generation_run_id,
  orchestrator_execution_id: body.orchestrator_execution_id ?? null,
  requirement_id: body.requirement_id,
  output_type: body.output_type ?? null,
  scheduled_date: body.scheduled_date ?? null,
  mission_type: body.mission_type ?? null,
  result: body.result ?? null,
  failed: body.failed === true,
  failure: body.failure ?? null,
  repair_attempt: Number(body.repair_attempt ?? 0),
} }];

return $input.all().map((item) => ({ json: {
  requirement_id: item.json.requirement_id,
  output_type: item.json.output_type,
  scheduled_date: item.json.scheduled_date,
  mission_type: item.json.mission_type ?? null,
  failed: true,
  worker_terminal: true,
  failure: item.json.failure ?? {
    requirement_id: item.json.requirement_id,
    error_message: 'Mission generation failed before deterministic validation.',
    repair_attempts: 0,
  },
} }));

return $input.all().map((item) => {
  const value = item.json;
  const transportMessage = value.error?.message ?? value.error ?? value.message;
  const errors = Array.isArray(value.errors)
    ? value.errors
    : value.valid === true
      ? []
      : [String(transportMessage || 'Django validation did not return a valid response.')];
  return { json: {
    generation_run_id: value.generation_run_id,
    orchestrator_execution_id: value.orchestrator_execution_id ?? null,
    requirement_id: value.requirement_id,
    output_type: value.output_type,
    scheduled_date: value.scheduled_date,
    mission_type: value.mission_type ?? null,
    result: value.result,
    repair_attempt: Number(value.repair_attempt ?? 0),
    review: value.review ?? null,
    validation_errors: value.validation_errors ?? [],
    validation: {
      valid: value.valid === true,
      errors,
      normalized_result: value.normalized_result ?? null,
    },
  } };
});

