function extractJsonText(value) {
  if (typeof value !== 'string' || !value.trim()) return '';
  let text = value.trim().replace(/^\uFEFF/, '');
  if (text.startsWith('```')) {
    const lines = text.split('\n');
    lines.shift();
    if (lines.length && lines[lines.length - 1].trim().startsWith('```')) lines.pop();
    text = lines.join('\n').trim();
  }

  const objectStart = text.indexOf('{');
  const arrayStart = text.indexOf('[');
  const starts = [objectStart, arrayStart].filter((index) => index >= 0);
  if (!starts.length) return text;
  const start = Math.min(...starts);
  const stack = [];
  let inString = false;
  let escaped = false;

  for (let index = start; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') inString = true;
    else if (character === '{' || character === '[') stack.push(character);
    else if (character === '}' || character === ']') {
      const expected = character === '}' ? '{' : '[';
      if (stack[stack.length - 1] === expected) stack.pop();
      if (stack.length === 0) return text.slice(start, index + 1).trim();
    }
  }
  return text.slice(start).trim();
}

function sanitizeJsonText(text) {
  let output = '';
  let inString = false;
  let escaped = false;

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      if (!escaped && character.charCodeAt(0) < 32) {
        if (character === '\n') output += '\\n';
        else if (character === '\r') output += '\\r';
        else if (character === '\t') output += '\\t';
        else output += '\\u' + character.charCodeAt(0).toString(16).padStart(4, '0');
        continue;
      }
      output += character;
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }

    if (character === '"') {
      inString = true;
      output += character;
      continue;
    }
    if (character === '_' && /\d/.test(text[index - 1] || '') && /\d/.test(text[index + 1] || '')) {
      continue;
    }
    if (character === '/' && text[index + 1] === '/') {
      while (index + 1 < text.length && text[index + 1] !== '\n') index += 1;
      continue;
    }
    if (character === '/' && text[index + 1] === '*') {
      index += 2;
      while (index < text.length - 1 && !(text[index] === '*' && text[index + 1] === '/')) index += 1;
      index += 1;
      continue;
    }
    if (character === ',') {
      let nextIndex = index + 1;
      while (/\s/.test(text[nextIndex] || '')) nextIndex += 1;
      if (text[nextIndex] === '}' || text[nextIndex] === ']') continue;
    }
    output += character === '\u00A0' ? ' ' : character;
  }
  return output;
}

function repairTerminalJsonStructure(text) {
  const stack = [];
  let inString = false;
  let escaped = false;
  let repaired = '';

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      repaired += character;
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') {
      inString = true;
      repaired += character;
    } else if (character === '{' || character === '[') {
      stack.push(character);
      repaired += character;
    } else if (character === '}' || character === ']') {
      const expectedOpening = character === '}' ? '{' : '[';
      if (stack[stack.length - 1] !== expectedOpening) {
        const onlyWhitespaceRemains = !text.slice(index + 1).trim();
        const matchingIndex = stack.lastIndexOf(expectedOpening);
        if (!onlyWhitespaceRemains || matchingIndex < 0) return null;
        repaired += stack.splice(matchingIndex + 1).reverse()
          .map((opening) => opening === '{' ? '}' : ']').join('');
      }
      stack.pop();
      repaired += character;
    } else {
      repaired += character;
    }
  }
  if (inString || escaped) return null;
  repaired += stack.reverse().map((opening) => opening === '{' ? '}' : ']').join('');
  return repaired === text ? null : repaired;
}

function parseAiJson(value) {
  const extracted = extractJsonText(value);
  if (!extracted) return { ok: false, error: 'AI returned an empty JSON response', repairs: [] };
  const sanitized = sanitizeJsonText(extracted);
  const candidates = [{ text: extracted, repairs: [] }];
  if (sanitized !== extracted) candidates.push({ text: sanitized, repairs: ['safe_json_syntax'] });

  for (const candidate of [...candidates]) {
    const terminal = repairTerminalJsonStructure(candidate.text);
    if (terminal !== null) {
      candidates.push({ text: terminal, repairs: [...candidate.repairs, 'terminal_structure'] });
    }
  }

  let firstError = null;
  const seen = new Set();
  for (const candidate of candidates) {
    if (seen.has(candidate.text)) continue;
    seen.add(candidate.text);
    try {
      let payload = JSON.parse(candidate.text);
      if (typeof payload === 'string') {
        const nested = extractJsonText(payload);
        if (nested && nested !== payload) payload = JSON.parse(sanitizeJsonText(nested));
      }
      return { ok: true, payload, repairs: candidate.repairs };
    } catch (error) {
      firstError = firstError || error;
    }
  }
  return {
    ok: false,
    error: firstError ? firstError.message : 'AI returned invalid JSON',
    repairs: [],
  };
}

return $input.all().map((item) => {
  const context = item.json;
  const content = context.choices?.[0]?.message?.content;
  const parsed = parseAiJson(content);
  let review;
  if (!parsed.ok || !parsed.payload || typeof parsed.payload !== 'object' || Array.isArray(parsed.payload)) {
    const transportMessage = context.error?.message ?? context.error ?? context.message;
    review = {
      verdict: 'revise',
      score: 0,
      issues: [{
        code: 'reviewer_response_invalid',
        message: 'Reviewer response was unavailable or invalid after retry: ' + String(transportMessage || parsed.error || 'invalid review object'),
        severity: 'medium',
      }],
    };
  } else {
    const candidate = parsed.payload;
    const verdict = String(candidate.verdict ?? '').toLowerCase();
    const score = Number(candidate.score);
    const issues = Array.isArray(candidate.issues) ? candidate.issues : [];
    review = {
      verdict: verdict === 'pass' || verdict === 'revise' ? verdict : 'revise',
      score: Number.isFinite(score) ? Math.max(0, Math.min(1, score)) : 0,
      issues: issues.map((issue) => ({
        code: String(issue?.code || 'review_issue'),
        message: String(issue?.message || 'Reviewer requested a revision.'),
        severity: ['low', 'medium', 'high'].includes(issue?.severity) ? issue.severity : 'medium',
      })),
    };
    if (!['pass', 'revise'].includes(verdict)) {
      review.issues.push({ code: 'reviewer_verdict_invalid', message: 'Reviewer returned an invalid verdict.', severity: 'medium' });
    }
  }
  return { json: {
    generation_run_id: context.generation_run_id,
    orchestrator_execution_id: context.orchestrator_execution_id ?? null,
    requirement_id: context.requirement_id,
    output_type: context.output_type,
    scheduled_date: context.scheduled_date,
    mission_type: context.mission_type ?? null,
    result: context.result,
    repair_attempt: Number(context.repair_attempt ?? 0),
    validation: context.validation,
    validation_errors: context.validation_errors ?? [],
    review,
    reviewer_json_repairs: parsed.repairs,
  } };
});

return $input.all().map((item) => {
  const value = item.json;
  const validationErrors = Array.isArray(value.validation?.errors)
    ? value.validation.errors
    : Array.isArray(value.validation_errors)
      ? value.validation_errors
      : [];
  return { json: {
    generation_run_id: value.generation_run_id,
    orchestrator_execution_id: value.orchestrator_execution_id ?? null,
    requirement_id: value.requirement_id,
    output_type: value.output_type,
    scheduled_date: value.scheduled_date,
    mission_type: value.mission_type ?? null,
    result: value.result,
    review: value.review ?? null,
    validation_errors: validationErrors,
    repair_attempt: Number(value.repair_attempt ?? 0) + 1,
  } };
});

