function extractJsonText(value) {
  if (typeof value !== 'string' || !value.trim()) return '';
  let text = value.trim().replace(/^\uFEFF/, '');
  if (text.startsWith('```')) {
    const lines = text.split('\n');
    lines.shift();
    if (lines.length && lines[lines.length - 1].trim().startsWith('```')) lines.pop();
    text = lines.join('\n').trim();
  }

  const objectStart = text.indexOf('{');
  const arrayStart = text.indexOf('[');
  const starts = [objectStart, arrayStart].filter((index) => index >= 0);
  if (!starts.length) return text;
  const start = Math.min(...starts);
  const stack = [];
  let inString = false;
  let escaped = false;

  for (let index = start; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') inString = true;
    else if (character === '{' || character === '[') stack.push(character);
    else if (character === '}' || character === ']') {
      const expected = character === '}' ? '{' : '[';
      if (stack[stack.length - 1] === expected) stack.pop();
      if (stack.length === 0) return text.slice(start, index + 1).trim();
    }
  }
  return text.slice(start).trim();
}

function sanitizeJsonText(text) {
  let output = '';
  let inString = false;
  let escaped = false;

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      if (!escaped && character.charCodeAt(0) < 32) {
        if (character === '\n') output += '\\n';
        else if (character === '\r') output += '\\r';
        else if (character === '\t') output += '\\t';
        else output += '\\u' + character.charCodeAt(0).toString(16).padStart(4, '0');
        continue;
      }
      output += character;
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }

    if (character === '"') {
      inString = true;
      output += character;
      continue;
    }
    if (character === '_' && /\d/.test(text[index - 1] || '') && /\d/.test(text[index + 1] || '')) {
      continue;
    }
    if (character === '/' && text[index + 1] === '/') {
      while (index + 1 < text.length && text[index + 1] !== '\n') index += 1;
      continue;
    }
    if (character === '/' && text[index + 1] === '*') {
      index += 2;
      while (index < text.length - 1 && !(text[index] === '*' && text[index + 1] === '/')) index += 1;
      index += 1;
      continue;
    }
    if (character === ',') {
      let nextIndex = index + 1;
      while (/\s/.test(text[nextIndex] || '')) nextIndex += 1;
      if (text[nextIndex] === '}' || text[nextIndex] === ']') continue;
    }
    output += character === '\u00A0' ? ' ' : character;
  }
  return output;
}

function repairTerminalJsonStructure(text) {
  const stack = [];
  let inString = false;
  let escaped = false;
  let repaired = '';

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      repaired += character;
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') {
      inString = true;
      repaired += character;
    } else if (character === '{' || character === '[') {
      stack.push(character);
      repaired += character;
    } else if (character === '}' || character === ']') {
      const expectedOpening = character === '}' ? '{' : '[';
      if (stack[stack.length - 1] !== expectedOpening) {
        const onlyWhitespaceRemains = !text.slice(index + 1).trim();
        const matchingIndex = stack.lastIndexOf(expectedOpening);
        if (!onlyWhitespaceRemains || matchingIndex < 0) return null;
        repaired += stack.splice(matchingIndex + 1).reverse()
          .map((opening) => opening === '{' ? '}' : ']').join('');
      }
      stack.pop();
      repaired += character;
    } else {
      repaired += character;
    }
  }
  if (inString || escaped) return null;
  repaired += stack.reverse().map((opening) => opening === '{' ? '}' : ']').join('');
  return repaired === text ? null : repaired;
}

function parseAiJson(value) {
  const extracted = extractJsonText(value);
  if (!extracted) return { ok: false, error: 'AI returned an empty JSON response', repairs: [] };
  const sanitized = sanitizeJsonText(extracted);
  const candidates = [{ text: extracted, repairs: [] }];
  if (sanitized !== extracted) candidates.push({ text: sanitized, repairs: ['safe_json_syntax'] });

  for (const candidate of [...candidates]) {
    const terminal = repairTerminalJsonStructure(candidate.text);
    if (terminal !== null) {
      candidates.push({ text: terminal, repairs: [...candidate.repairs, 'terminal_structure'] });
    }
  }

  let firstError = null;
  const seen = new Set();
  for (const candidate of candidates) {
    if (seen.has(candidate.text)) continue;
    seen.add(candidate.text);
    try {
      let payload = JSON.parse(candidate.text);
      if (typeof payload === 'string') {
        const nested = extractJsonText(payload);
        if (nested && nested !== payload) payload = JSON.parse(sanitizeJsonText(nested));
      }
      return { ok: true, payload, repairs: candidate.repairs };
    } catch (error) {
      firstError = firstError || error;
    }
  }
  return {
    ok: false,
    error: firstError ? firstError.message : 'AI returned invalid JSON',
    repairs: [],
  };
}

return $input.all().map((item) => {
  const value = item.json;
  const content = value.choices?.[0]?.message?.content;
  const parsed = parseAiJson(content);
  const transportMessage = value.error?.message ?? value.error ?? value.message;
  return { json: {
    generation_run_id: value.generation_run_id,
    orchestrator_execution_id: value.orchestrator_execution_id,
    requirement_id: value.requirement_id,
    output_type: value.output_type,
    scheduled_date: value.scheduled_date,
    mission_type: value.mission_type ?? null,
    call_index: value.call_index,
    expected_calls: value.expected_calls,
    difficulty: value.difficulty ?? null,
    generator_ok: parsed.ok,
    generator_payload: parsed.ok ? parsed.payload : null,
    generator_error: parsed.ok ? null : String(transportMessage || parsed.error || 'Generator response unavailable.'),
    generator_json_repairs: parsed.repairs,
  } };
});

const start = $('Start Generation V2').first().json;
const body = start.body ?? start;
const requirements = Array.isArray(body.requirements) ? body.requirements : [];
const calls = $input.all().map((item) => item.json);

function failed(requirement, message) {
  return { json: {
    generation_run_id: body.generation_run_id,
    orchestrator_execution_id: $execution.id,
    requirement_id: requirement.id,
    output_type: requirement.output_type ?? null,
    scheduled_date: requirement.scheduled_date ?? null,
    mission_type: requirement.mission_type ?? null,
    failed: true,
    failure: { requirement_id: requirement.id, error_message: message, repair_attempts: 0 },
  } };
}

const output = [];
for (const requirement of requirements) {
  const expected = Array.isArray(requirement.generator_requests) ? requirement.generator_requests.length : 0;
  const group = calls.filter((call) => call.requirement_id === requirement.id)
    .sort((left, right) => Number(left.call_index) - Number(right.call_index));
  if (!expected) {
    output.push(failed(requirement, 'Requirement contains no generator requests.'));
    continue;
  }
  if (group.length !== expected) {
    output.push(failed(requirement, 'Generator response count mismatch: expected ' + expected + ', received ' + group.length + '.'));
    continue;
  }
  const errors = group.filter((call) => call.generator_ok !== true)
    .map((call) => 'call ' + (Number(call.call_index) + 1) + ': ' + call.generator_error);
  if (errors.length) {
    output.push(failed(requirement, 'Generator failed after retry. ' + errors.join(' | ')));
    continue;
  }

  let result;
  if (['quiz_mission', 'training_task', 'training_chat'].includes(requirement.output_type)) {
    if (group.length !== 1) {
      output.push(failed(requirement, requirement.output_type + ' requires exactly one generator result.'));
      continue;
    }
    result = { payload: group[0].generator_payload };
  } else if (requirement.output_type === 'task_mission') {
    const variants = {};
    let variantError = null;
    for (const call of group) {
      if (!['easy', 'medium', 'hard'].includes(call.difficulty)) {
        variantError = 'Invalid task difficulty: ' + call.difficulty;
        break;
      }
      if (variants[call.difficulty]) {
        variantError = 'Duplicate task difficulty: ' + call.difficulty;
        break;
      }
      variants[call.difficulty] = call.generator_payload;
    }
    const missing = ['easy', 'medium', 'hard'].filter((difficulty) => !variants[difficulty]);
    if (!variantError && missing.length) variantError = 'Missing task variants: ' + missing.join(', ');
    if (variantError) {
      output.push(failed(requirement, variantError));
      continue;
    }
    result = { variants };
  } else {
    output.push(failed(requirement, 'Unsupported output_type: ' + requirement.output_type));
    continue;
  }

  output.push({ json: {
    generation_run_id: body.generation_run_id,
    orchestrator_execution_id: $execution.id,
    requirement_id: requirement.id,
    output_type: requirement.output_type,
    scheduled_date: requirement.scheduled_date ?? null,
    mission_type: requirement.mission_type ?? null,
    result,
    failed: false,
  } });
}
return output;

return $input.all().map((item) => {
  const value = item.json;
  if (value.worker_terminal === true && value.requirement_id) {
    return { json: {
      requirement_id: value.requirement_id,
      output_type: value.output_type ?? null,
      scheduled_date: value.scheduled_date ?? null,
      mission_type: value.mission_type ?? null,
      result: value.result ?? null,
      validation: value.validation ?? null,
      review: value.review ?? null,
      failed: value.failed === true,
      failure: value.failure ?? null,
    } };
  }
  const message = value.error?.message ?? value.error ?? value.message ?? 'Mission worker returned an invalid response.';
  return { json: {
    requirement_id: value.requirement_id ?? 'unknown-requirement',
    output_type: value.output_type ?? null,
    scheduled_date: value.scheduled_date ?? null,
    mission_type: value.mission_type ?? null,
    failed: true,
    failure: {
      requirement_id: value.requirement_id ?? 'unknown-requirement',
      error_message: String(message),
      repair_attempts: 0,
    },
  } };
});

const start = $('Start Generation V2').first().json;
const body = start.body ?? start;
const expectedIds = (Array.isArray(body.requirements) ? body.requirements : []).map((item) => item.id);
const items = $input.all().map((item) => item.json);
const byId = new Map(items.map((item) => [item.requirement_id, item]));
const ordered = expectedIds.map((requirementId) => byId.get(requirementId) ?? {
  requirement_id: requirementId,
  failed: true,
  failure: { requirement_id: requirementId, error_message: 'Mission worker result is missing.', repair_attempts: 0 },
});
const successful = ordered.filter((item) => item.failed !== true && item.result);
const failed = ordered.filter((item) => item.failed === true || !item.result);
const reviews = successful.map((item) => item.review).filter(Boolean);
const scores = reviews.map((review) => Number(review.score)).filter(Number.isFinite);
const averageScore = scores.length ? scores.reduce((sum, score) => sum + score, 0) / scores.length : 1;
return [{ json: {
  results: successful.map((item) => ({ requirement_id: item.requirement_id, ...item.result })),
  failed_requirements: failed.map((item) => item.failure ?? {
    requirement_id: item.requirement_id,
    error_message: 'Mission worker failed without a structured error.',
    repair_attempts: 0,
  }),
  review_report: {
    verdict: 'pass',
    score: averageScore,
    issues: reviews.flatMap((review) => review.issues ?? []),
    partial_success: failed.length > 0 && successful.length > 0,
  },
} }];

